+// ---------------------------------------------------------------------------
+// Tests for Assembler::load_const_optimized()
+//
+// Recommendation for Development
+//
+//   * Create a copy Assembler::load_const_optimized_new()
+//   * Make enhancements in load_const_optimized_new()
+//   * The tests below will also test load_const_optimized_new()
+//
+template <typename T, typename = void>
+struct has_load_const_optimized_new : std::false_type {};
+template <typename T>
+    struct has_load_const_optimized_new < T,
+    std::void_t < decltype(std::declval<T &>()
+                           .load_const_optimized_new(std::declval<Register>(), (long)0, std::declval<Register>(), false))>>
+    : std::true_type {};
+
+static constexpr bool HAS_LOAD_CONST_NEW =
+    has_load_const_optimized_new<MacroAssembler>::value;
+
+// HAS_LOAD_CONST_NEW de depends on the exact signature of Assembler::load_const_optimized()
+static_assert(std::is_same_v<int (Assembler::*)(Register, long, Register, bool),
+              decltype(static_cast<int (Assembler::*)(Register, long, Register, bool)>(&Assembler::load_const_optimized))>,
+              "Assembler::load_const_optimized signature changed; update this test");
+
+// Format a 64-bit value as "0x..." into a caller-owned buffer, for messages.
+static const char* hex64(uint64_t x, char* buf, size_t len) {
+  (void)os::snprintf(buf, len, UINT64_FORMAT_X_0, x);
+  return buf;
+}
+
+typedef long (*load_const_func)();
+
+// A stub generated by gen_load_const, ready to be executed by run_load_const.
+struct load_const_stub {
+  long          x;                  // constant being loaded
+  Register      d;                  // destination register
+  bool          have_tmp;           // whether a tmp register was provided
+  bool          return_simm16_rest; // the return_simm16_rest argument
+  bool          use_new;            // old vs. new implementation
+  address       entry;              // entry point to call
+  int           simm16_rest;        // signed remainder returned by load_const_optimized
+  int           insns;              // number of instructions emitted
+};
+
+// Emit load_const_optimized (or, when use_new, the new version). The returned
+// stub records everything run_load_const needs to execute it later.
+template <typename Masm>
+static load_const_stub gen_load_const(Masm& _masm, long x, Register d,
+                                      bool have_tmp, bool return_simm16_rest, bool use_new) {
+  load_const_stub stub;
+  stub.x                  = x;
+  stub.d                  = d;
+  stub.have_tmp           = have_tmp;
+  stub.return_simm16_rest = return_simm16_rest;
+  stub.use_new            = use_new;
+
+  if (Verbose) {
+    tty->print_cr("gen_load_const: x=" UINT64_FORMAT_X_0 " d=%s tmp=%s return_simm16_rest=%s use_new=%s",
+                  x,
+                  (d == R0 ? "R0" : "R3_RET"),
+                  (have_tmp ? "R4_ARG2" : "noreg"),
+                  (return_simm16_rest ? "true" : "false"),
+                  (use_new ? "true" : "false"));
+  }
+
+  Register tmp = have_tmp ? R4_ARG2 : noreg;
+  stub.entry = _masm.function_entry();
+  address load_const_pc = _masm.pc();
+  if constexpr (has_load_const_optimized_new<Masm>::value) {
+    stub.simm16_rest = use_new
+        ? _masm.load_const_optimized_new(d, x, tmp, return_simm16_rest)
+        : _masm.load_const_optimized(d, x, tmp, return_simm16_rest);
+  } else {
+    assert(!use_new, "no load_const_optimized_new available");
+    stub.simm16_rest = _masm.load_const_optimized(d, x, tmp, return_simm16_rest);
+  }
+  stub.insns = (int)((_masm.pc() - load_const_pc) / BytesPerInstWord);
+  _masm.mr_if_needed(R3_RET, d);
+  _masm.blr();
+
+  return stub;
+}
+
+// Execute a stub generated by gen_load_const and return the loaded value.
+static long run_load_const(const load_const_stub& stub) {
+  long result_base = ((load_const_func)stub.entry)();
+  long result = result_base + stub.simm16_rest;
+
+  if (Verbose) {
+    tty->print_cr("run_load_const: x=" UINT64_FORMAT_X_0 " insns=%d result_base=" UINT64_FORMAT_X_0
+                  " simm16_rest=%d result=" UINT64_FORMAT_X_0,
+                  stub.x, stub.insns, result_base, stub.simm16_rest, result);
+  }
+
+  return result;
+}
+
+// Verify that load_const_optimized loads x correctly for all combinations of
+// d (R3_RET / R0), tmp (noreg / R4_ARG2) and return_simm16_rest (false / true),
+// and that the new version never emits more instructions than the old one.
+static void check_constant(long x) {
+  char xb[24];
+  const Register dregs[] = { R3_RET, R0 };
+
+  ResourceMark rm;
+  BufferBlob* bb = BufferBlob::create("load_const_optimized_test", 4096);
+  guarantee(bb != nullptr, "allocation failed");
+  CodeBuffer code(bb);
+  MacroAssembler _masm(&code);
+
+  // 2 destination registers x 4 modes, each optionally doubled to also test the
+  // new implementation when one is available.
+  constexpr int kVariants = 2 * 4 * (HAS_LOAD_CONST_NEW ? 2 : 1);
+  load_const_stub stubs[kVariants];
+  int n = 0;
+  for (Register d : dregs) {
+    for (int m = 0; m < 4; m++) {
+      bool have_tmp           = (m & 1) != 0;
+      bool return_simm16_rest = (m & 2) != 0;
+      stubs[n++] = gen_load_const(_masm, x, d, have_tmp, return_simm16_rest, false);
+      if (HAS_LOAD_CONST_NEW) {
+        stubs[n++] = gen_load_const(_masm, x, d, have_tmp, return_simm16_rest, true);
+      }
+    }
+  }
+
+  _masm.invalidate_icache();
+
+  for (int i = 0; i < n; i++) {
+    const load_const_stub& s = stubs[i];
+    long result = run_load_const(s);
+    if (!s.use_new) {
+      EXPECT_EQ(result, x)
+          << "wrong value for x=" << hex64((uint64_t)x, xb, sizeof(xb))
+          << (s.d == R0             ? " (d=R0)"               : " (d=R3_RET)")
+          << (s.have_tmp            ? " (with tmp)"           : " (no tmp)")
+          << (s.return_simm16_rest  ? " (return_simm16_rest)" : "");
+    } else {
+      // The new stub was generated right after its old counterpart.
+      const load_const_stub& old = stubs[i - 1];
+      EXPECT_EQ(result, x)
+          << "wrong value (new) for x=" << hex64((uint64_t)x, xb, sizeof(xb))
+          << (s.d == R0             ? " (d=R0)"               : " (d=R3_RET)")
+          << (s.have_tmp            ? " (with tmp)"           : " (no tmp)")
+          << (s.return_simm16_rest  ? " (return_simm16_rest)" : "");
+      EXPECT_LE(s.insns, old.insns)
+          << "load_const_optimized_new emitted more instructions than old for x="
+          << hex64((uint64_t)x, xb, sizeof(xb))
+          << " (" << s.insns << " vs " << old.insns << ")"
+          << (s.d == R0             ? " (d=R0)"               : " (d=R3_RET)")
+          << (s.have_tmp            ? " (with tmp)"           : " (no tmp)")
+          << (s.return_simm16_rest  ? " (return_simm16_rest)" : "");
+    }
+  }
+
+  BufferBlob::free(bb);
+}
